    /* ===== SKIP TO CONTENT ===== */
    .skip-to-content {
      position: absolute; top: -50px; left: 16px; background: var(--accent);
      color: white; padding: 12px 16px; text-decoration: none;
      border-radius: 8px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 16px; opacity: 1; pointer-events: auto; }

    /* ===== POSTER LAYOUT ===== */
    #main-content {
      display: flex; flex-direction: column; justify-content: space-between;
      flex: 1; position: relative; z-index: 1;
      padding: 60px 80px;
    }

    .poster-header {
      text-align: center; margin-bottom: 50px;
    }
    .poster-header h1 {
      background: linear-gradient(135deg, var(--text) 30%, var(--accent-secondary) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      margin-bottom: 16px;
    }
    .poster-header p {
      font-size: 28px; color: var(--accent); text-transform: uppercase; letter-spacing: 0.08em; font-weight: 600;
    }

    .hero-stat {
      display: flex; align-items: center; justify-content: space-between;
      background: linear-gradient(135deg, var(--surface) 0%, rgba(15,23,42,0.4) 100%);
      border: 1px solid var(--accent);
      border-radius: 20px;
      padding: 40px 60px;
      margin-bottom: 40px;
      box-shadow: 0 0 40px rgba(14, 165, 233, 0.1);
    }
    .hero-number {
      font-size: 110px; font-weight: 800; color: var(--accent);
      line-height: 1; margin-bottom: 8px; letter-spacing: -0.05em;
    }
    .hero-label {
      font-size: 32px; font-weight: 600; text-transform: uppercase; color: var(--text); letter-spacing: 0.05em;
    }
    .hero-sub {
      font-size: 24px; color: var(--text-secondary); margin-top: 12px; max-width: 400px;
    }

    .poster-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
      flex: 1;
    }

    .chart-container {
      position: relative; height: 360px; padding: 24px; background: var(--surface); border-radius: 12px; border: 1px solid var(--border);
    }
    .chart-tall {
      height: 480px;
    }

    .highlight-card {
      background: linear-gradient(135deg, rgba(14,165,233,0.1) 0%, rgba(45,212,191,0.05) 100%);
      border: 1px solid var(--accent);
    }
    .highlight-number { font-size: 64px; font-weight: 700; color: var(--accent); line-height: 1.1; margin-bottom: 4px; }

    .social-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 32px;
    }
    .social-item {
      display: flex; flex-direction: column; background: var(--bg); padding: 20px; border-radius: 12px; border: 1px solid var(--border);
    }
    .social-val { font-size: 36px; font-weight: 700; color: var(--text); }
    .social-lbl { font-size: 16px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.05em;}

    .poster-footer {
      margin-top: 40px;
      background: var(--surface);
      border: 1px solid var(--accent-secondary);
      border-radius: 20px;
      padding: 40px 60px;
      display: flex; align-items: center; justify-content: space-between;
    }
    .footer-content h3 { font-size: 40px; color: var(--text); margin-bottom: 8px;}
    .footer-content p { font-size: 22px; color: var(--text-secondary); max-width: 600px;}
    .footer-value { font-size: 80px; font-weight: 800; color: var(--accent-secondary); line-height: 1; }

  </style>
</head>
<body>
  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <main id="main-content" role="main">
    <header class="poster-header animate">
      <h1>Global Internet Usage</h1>
      <p>A Cross-Country Comparison (2025)</p>
    </header>

    <section class="hero-stat animate delay-1">
      <div>
        <div class="hero-label">The World's Digital Population</div>
        <p class="hero-sub">Internet adoption continues to grow, capturing roughly 68% of the world's population.</p>
      </div>
      <div style="text-align: right;">
        <div class="hero-number">~<span data-count="5.56">0</span>B</div>
        <div class="hero-label" style="color: var(--accent); font-size: 28px;">Global Internet Users</div>
      </div>
    </section>

    <div class="poster-grid">
      <!-- Left Column -->
      <div style="display: flex; flex-direction: column; gap: 40px;">
        <section class="card animate delay-2">
          <h2>Internet Penetration Rates</h2>
          <p class="text-secondary" style="margin-bottom: 24px;">Comparing percentage of population connected across selected countries.</p>
          <div role="img" aria-label="Bar chart showing internet penetration rates by country, led by South Korea at 98%">
            <div class="chart-container chart-tall">
              <canvas id="penetrationChart"></canvas>
            </div>
          </div>
        </section>

        <section class="card highlight-card animate delay-3">
          <h2>The Giants of Asia</h2>
          <p style="margin-bottom: 24px;">China and India represent a massive share of the global digital population.</p>
          <div style="display: flex; justify-content: space-between; gap: 24px;">
            <div style="flex: 1; background: rgba(0,0,0,0.2); padding: 24px; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);">
              <div class="highlight-number">1.09<span style="font-size:36px">B</span></div>
              <div style="font-weight: 600; font-size: 22px;">China</div>
              <div class="text-secondary">~76% Penetration</div>
            </div>
            <div style="flex: 1; background: rgba(0,0,0,0.2); padding: 24px; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);">
              <div class="highlight-number">900<span style="font-size:36px">M</span></div>
              <div style="font-weight: 600; font-size: 22px;">India</div>
              <div class="text-secondary">~62% Penetration</div>
            </div>
          </div>
        </section>
      </div>

      <!-- Right Column -->
      <div style="display: flex; flex-direction: column; gap: 40px;">
        <section class="card animate delay-4" style="flex: 1;">
          <h2>How People Spend Time Online</h2>
          <p class="text-secondary" style="margin-bottom: 32px;">Daily social media usage continues to trend upward.</p>

          <div style="display: flex; align-items: center; gap: 32px; background: var(--surface-hover); padding: 32px; border-radius: 16px; border-left: 6px solid var(--accent); margin-bottom: 32px;">
            <div style="font-size: 84px; font-weight: 800; color: var(--accent); line-height: 1;">~<span data-count="143">0</span></div>
            <div>
              <div style="font-size: 24px; font-weight: 700;">Minutes Per Day</div>
              <div class="text-secondary">Global average time spent on social media</div>
            </div>
          </div>

          <h3 style="border-bottom: 1px solid var(--border); padding-bottom: 12px;">Top Platforms by Active Users</h3>
          <div class="social-grid">
            <div class="social-item">
              <span class="social-val">~3.1B</span>
              <span class="social-lbl">Facebook</span>
            </div>
            <div class="social-item">
              <span class="social-val">~2.5B</span>
              <span class="social-lbl">YouTube</span>
            </div>
            <div class="social-item">
              <span class="social-val">~2.4B</span>
              <span class="social-lbl">WhatsApp</span>
            </div>
            <div class="social-item">
              <span class="social-val">~2.0B</span>
              <span class="social-lbl">Instagram</span>
            </div>
            <div class="social-item" style="grid-column: span 2; align-items: center; text-align: center; border-color: var(--accent-secondary); background: rgba(45,212,191,0.05);">
              <span class="social-val" style="color: var(--accent-secondary);">~1.6B</span>
              <span class="social-lbl">TikTok</span>
            </div>
          </div>
        </section>
      </div>
    </div>

    <!-- Footer -->
    <section class="poster-footer animate delay-5">
      <div class="footer-content">
        <h3>The Digital Economy Impact</h3>
        <p>Internet usage is the primary driver of global e-commerce and digital market expansion.</p>
      </div>
      <div style="text-align: right;">
        <div class="footer-value">$<span data-count="8.0">0</span>T</div>
        <div style="font-size: 22px; font-weight: 600; color: var(--text-secondary); text-transform: uppercase;">Retail E-Commerce by 2027</div>
      </div>
    </section>
  </main>

  <script>
    Chart.defaults.animation = false;

    // === Menu & Interactivity ===
    function toggleMenu() { 
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open'); 
    }
    document.addEventListener('click', e => { 
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === Theme ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === Scroll Reveal ===
    document.querySelectorAll('[data-reveal]').forEach(el => el.classList.add('reveal'));
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));

    // === Number Counter ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count);
        var isFloat = target % 1 !== 0 || el.dataset.count.indexOf('.') !== -1;
        var start = performance.now(), duration = 1500;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
          var val = target * eased;
          el.textContent = isFloat ? val.toFixed(2) : Math.round(val);
          if (p < 1) requestAnimationFrame(tick);
          else el.textContent = isFloat ? target.toFixed(2) : target;
        })(start);
      });
    }
    document.addEventListener('DOMContentLoaded', animateCounters); // Auto start for poster

    // === Download PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2 });
        var a = document.createElement('a'); a.href = url;
        a.download = 'global-internet-usage-poster.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // === Chart.js Configuration ===
    var chartsBuilt = false;

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;

      var isDark = document.documentElement.classList.contains('theme-dark');
      var colors = {
        text: isDark ? '#f8fafc' : '#0f172a',
        grid: isDark ? 'rgba(14, 165, 233, 0.1)' : 'rgba(15, 23, 42, 0.1)',
        bar: isDark ? '#0ea5e9' : '#0284c7',
        barHover: isDark ? '#38bdf8' : '#0369a1',
      };

      if (window.penetrationChart) {
        try { window.penetrationChart.destroy(); } catch(e) {}
      }

      var ctx = resetCanvas('penetrationChart');
      if (ctx) {
        window.penetrationChart = new Chart(ctx, {
          type: 'bar',
          data: {
            labels: ['South Korea', 'UK', 'Germany', 'Japan', 'USA', 'Brazil', 'Indonesia', 'China', 'India', 'Nigeria'],
            datasets: [{
              label: 'Penetration Rate (%)',
              data: [98, 97, 96, 95, 95, 88, 78, 76, 62, 52],
              backgroundColor: function(context) {
                var value = context.dataset.data[context.dataIndex];
                if (value > 90) return colors.bar;
                if (value > 70) return isDark ? 'rgba(14, 165, 233, 0.7)' : 'rgba(2, 132, 199, 0.7)';
                return isDark ? 'rgba(14, 165, 233, 0.4)' : 'rgba(2, 132, 199, 0.4)';
              },
              borderRadius: 6,
              barPercentage: 0.7
            }]
          },
          options: {
            indexAxis: 'y',
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            plugins: {
              legend: { display: false },
              tooltip: {
                enabled: true,
                padding: 12,
                cornerRadius: 8,
                callbacks: {
                  label: function(context) { return context.raw + '%'; }
                }
              }
            },
            scales: {
              x: {
                max: 100,
                grid: { color: colors.grid, drawBorder: false },
                ticks: { color: colors.text, font: { size: 14, family: 'Inter' } }
              },
              y: {
                grid: { display: false },
                ticks: { color: colors.text, font: { size: 15, family: 'Inter', weight: '600' } }
              }
            },
            layout: { padding: { top: 10, bottom: 10, left: 10, right: 20 } }
          }
        });
      }

      chartsBuilt = true;
    }

    function onThemeChange() { 
      chartsBuilt = false; 
      setTimeout(buildCharts, 50); 
    }

    document.addEventListener('DOMContentLoaded', buildCharts);
  </script>
</body>
</html>
